function ConfirmDeleteDialog({ dialogRef, imageTitle, onConfirm }) {
  const titleId = useId();
  const descId = useId();
  const cancelRef = useRef(null);

  const close = useCallback((reason) => {
    if (dialogRef.current && dialogRef.current.open) {
      dialogRef.current.close(reason);
    }
  }, [dialogRef]);

  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    const handleClose = () => {
      if (dlg.returnValue === "delete") onConfirm();
    };
    // Click on backdrop closes (cancel)
    const handleClick = (e) => {
      if (e.target === dlg) close("cancel");
    };
    dlg.addEventListener("close", handleClose);
    dlg.addEventListener("click", handleClick);
    return () => {
      dlg.removeEventListener("close", handleClose);
      dlg.removeEventListener("click", handleClick);
    };
  }, [dialogRef, onConfirm, close]);

  // Focus the safe (Cancel) button when the dialog opens — never auto-focus the destructive action.
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    const observer = new MutationObserver(() => {
      if (dlg.open && cancelRef.current) {
        cancelRef.current.focus();
      }
    });
    observer.observe(dlg, { attributes: true, attributeFilter: ["open"] });
    return () => observer.disconnect();
  }, [dialogRef]);

  return (
    <dialog ref={dialogRef}
            className="confirm-dialog"
            aria-labelledby={titleId}
            aria-describedby={descId}>
      <form method="dialog" className="dialog-inner">
        <div className="dialog-header">
          <span className="dialog-icon" aria-hidden="true">
            <Icon name="alert" />
          </span>
          <div>
            <h2 id={titleId} className="dialog-title">Delete this image?</h2>
            <p id={descId} className="dialog-description">
              "{imageTitle}" will be permanently removed from your library. This action can't be undone.
            </p>
          </div>
        </div>
        <div className="dialog-actions">
          <button ref={cancelRef} type="button" className="btn" value="cancel"
                  onClick={() => close("cancel")}>
            Cancel
          </button>
          <button type="button" className="btn btn-danger" value="delete"
                  onClick={() => close("delete")}>
            <Icon name="trash" className="icon" />
            Delete image
          </button>
        </div>
      </form>
    </dialog>
  );
}

function ImagePreview() {
  const dialogRef = useRef(null);
  const triggerRef = useRef(null);
  const [deleted, setDeleted] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");
  const emptyStateRef = useRef(null);

  useEffect(() => {
    if (deleted && emptyStateRef.current) {
      emptyStateRef.current.focus();
    }
  }, [deleted]);

  const image = {
    title: "Sunrise over the dunes",
    src: "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=1200&q=80",
    alt: "A photograph of orange sunrise light spreading across rolling sand dunes.",
    uploaded: "May 4, 2026",
    size: "3.2 MB",
    dimensions: "4032 × 3024",
  };

  const openDialog = () => {
    if (dialogRef.current && !dialogRef.current.open) {
      dialogRef.current.showModal();
    }
  };

  const handleConfirmDelete = () => {
    setDeleted(true);
    setStatusMessage(`"${image.title}" was deleted from your library.`);
  };

  return (
    <>
      <nav className="breadcrumbs" aria-label="Breadcrumb">
        <ol>
          <li><a href="#library">Library</a></li>
          <li><a href="#photos">Photos</a></li>
          <li aria-current="page">{deleted ? "Deleted" : image.title}</li>
        </ol>
      </nav>

      {!deleted ? (
        <article className="preview-card" aria-labelledby="image-title">
          <div className="image-frame">
            <img src={image.src} alt={image.alt} />
          </div>
          <div className="preview-body">
            <div className="preview-meta">
              <h1 id="image-title">{image.title}</h1>
              <dl>
                <dt>Uploaded</dt><dd>{image.uploaded}</dd>
                <dt>Size</dt><dd>{image.size}</dd>
                <dt>Dimensions</dt><dd>{image.dimensions}</dd>
              </dl>
            </div>
            <div className="preview-actions">
              <button type="button" className="btn">
                <Icon name="download" className="icon" />
                Download
              </button>
              <button type="button"
                      ref={triggerRef}
                      className="trigger btn btn-ghost-danger"
                      onClick={openDialog}
                      aria-haspopup="dialog">
                <Icon name="trash" className="icon" />
                Delete
              </button>
            </div>
          </div>
        </article>
      ) : (
        <div className="empty-state" role="region" aria-label="Empty library state">
          <p><strong>This image has been deleted.</strong></p>
          <p>It is no longer available in your library.</p>
        </div>
      )}

      <div className="status-region" role="status" aria-live="polite">
        {statusMessage}
      </div>

      <ConfirmDeleteDialog
        dialogRef={dialogRef}
        imageTitle={image.title}
        onConfirm={handleConfirmDelete}
      />
    </>
  );
}

function App() {
  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <header className="site-header">
        <div className="inner">
          <div className="brand">Lumen Library</div>
          <nav className="site-nav" aria-label="Primary">
            <ul>
              <li><a href="#library" aria-current="page">Library</a></li>
              <li><a href="#albums">Albums</a></li>
              <li><a href="#shared">Shared</a></li>
            </ul>
          </nav>
        </div>
      </header>
      <main id="main">
        <ImagePreview />
      </main>
    </>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<StrictMode><App /></StrictMode>);
